window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6a715cb7fcb8f8f8"]={"versions": [{"id": "FIG-6a715cb7fcb8f8f8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des High-Level-Designs für Kryptoschlüssel-Slots (Crypto Key Slots) innerhalb des Manifest-Modells der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die Entwurfselemente zur Zuweisung, Konfiguration und Nutzungsbeziehung von kryptografischen Schlüsselslots auf Maschinenebene (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>): Enthält die Attribute <code>accessControl: AccessControlEnum [0..1]</code>, <code>pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>pnResetTimer: TimeValue [0..1]</code>. Es besitzt eine splitbare Komposition (<code>«atpSplitable»</code>) mit der Rolle <code>+cryptoKeySlot</code> und Multiplizität <code>0..*</code> zu <code>CryptoKeySlotDesign</code>.</li>\n<li><code>CryptoKeySlotDesign</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert die Konfiguration eines Schlüssel-Slots mit den Attributen <code>cryptoAlgorithmId: String [0..1]</code>, <code>cryptoObjectType: String [0..1]</code>, <code>shared: Boolean [0..1]</code> und <code>slotCapacity: PositiveInteger [0..1]</code>. Es referenziert über zwei ungerichtete Assoziationen <code>CryptoKeySlotUsageDesign</code> mit den Rollen <code>+user</code> (Multiplizität <code>0..<em></code>) und <code>+owner</code> (Multiplizität <code>0..</em></code>).</li>\n<li><code>CryptoKeySlotUserDesign</code> (Spezialisierung von <code>UploadableDesignElement</code>): Besitzt eine splitbare Komposition (<code>«atpSplitable»</code>) mit der Rolle <code>+keySlotUsage</code> und Multiplizität <code>0..*</code> zu <code>CryptoKeySlotUsageDesign</code>.</li>\n<li><code>CryptoKeySlotUsageDesign</code> (Spezialisierung von <code>Identifiable</code>): Dient als Verbindungselement zwischen dem Schlüsselslot-Nutzerdesign und dem konkreten <code>CryptoKeySlotDesign</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltenszustände. Die Beziehungen spezifizieren strukturelle Besitzverhältnisse (Kompositionen) und Referenzen zwischen Entwurfselementen während der Systemdesign- bzw. Manifest-Modellierungsphase.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Attribute legen die formale Struktur für die Definition von Krypto-Schlüsselslots und deren Besitz- sowie Zugriffsrechte im Maschinen-Manifest fest. <code>«atpSplitable»</code> ermöglicht die Aufteilung von Modellelementen über mehrere ARXML-Dateien. Multiplizitäten von <code>0..*</code> und optionale Attribute (<code>[0..1]</code>) definieren zulässige Konfigurationsbereiche für Modellierungs- und Validierungswerkzeuge.</p>"}, {"id": "FIG-1ac8455af7cb8ab9", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des High-Level-Designs für Kryptoschlüssel-Slots (Crypto Key Slots) innerhalb des Manifest-Modells der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die Entwurfselemente zur Zuweisung, Konfiguration und Nutzungsbeziehung von kryptografischen Schlüsselslots auf Maschinenebene (<code>MachineDesign</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>): Enthält die Attribute <code>accessControl: AccessControlEnum [0..1]</code>, <code>pncPrepareSleepTimer: TimeValue [0..1]</code> und <code>pnResetTimer: TimeValue [0..1]</code>. Es besitzt eine splitbare Komposition (<code>«atpSplitable»</code>) mit Rolle <code>+cryptoKeySlot</code> und Multiplizität <code>0..*</code> zu <code>CryptoKeySlotDesign</code>.</li>\n<li><code>CryptoKeySlotDesign</code> (Spezialisierung von <code>Identifiable</code>): Beinhaltet das Attribut <code>shared: Boolean [0..1]</code>. Es besitzt eine splitbare Komposition (<code>«atpSplitable»</code>) mit Rolle <code>+algorithmDescription</code> und Multiplizität <code>0..<em></code> zu <code>CryptoKeySlotDesignDescription</code>. Es referenziert über zwei Assoziationen <code>CryptoKeySlotUsageDesign</code> mit den Rollen <code>+user</code> (Multiplizität <code>0..</em></code>) und <code>+owner</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>CryptoKeySlotDesignDescription</code>: Enthält die Attribute <code>cryptoAlgorithmId: String [0..1]</code> und <code>cryptoObjectType: String [0..1]</code>.</li>\n<li><code>CryptoKeySlotUserDesign</code> (Spezialisierung von <code>UploadableDesignElement</code>): Besitzt eine splitbare Komposition (<code>«atpSplitable»</code>) mit Rolle <code>+keySlotUsage</code> und Multiplizität <code>0..*</code> zu <code>CryptoKeySlotUsageDesign</code>.</li>\n<li><code>CryptoKeySlotUsageDesign</code> (Spezialisierung von <code>Identifiable</code>): Vermittelt die Nutzungs- und Eigentümerbeziehungen zu <code>CryptoKeySlotDesign</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltenszustände. Die Beziehungen spezifizieren strukturelle Besitzverhältnisse (Kompositionen) und Referenzen zwischen Entwurfselementen während der Systemdesign- bzw. Manifest-Modellierungsphase.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Attribute legen die formale Struktur für die Definition von Krypto-Schlüsselslots, deren Algorithmusbeschreibungen sowie deren Besitz- und Zugriffsrechte im Maschinen-Manifest fest. Die Auslagerung der Algorithmenkonfiguration in <code>CryptoKeySlotDesignDescription</code> mit splitbarer Komposition (<code>«atpSplitable»</code>, Multiplizität <code>0..<em></code>) ermöglicht die Zuordnung mehrerer Algorithmusbeschreibungen zu einem Slot. Multiplizitäten von <code>0..</em></code> und optionale Attribute (<code>[0..1]</code>) definieren die Randbedingungen für Validierungs- und Codegenerierungswerkzeuge.</p>"}], "trans": [{"from": "FIG-6a715cb7fcb8f8f8", "to": "FIG-1ac8455af7cb8ab9", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>CryptoKeySlotDesign</code> entfallen die Attribute <code>cryptoAlgorithmId: String [0..1]</code>, <code>cryptoObjectType: String [0..1]</code> und <code>slotCapacity: PositiveInteger [0..1]</code>.</li>\n<li>Neu eingeführt wird die Meta-Klasse <code>CryptoKeySlotDesignDescription</code> mit den Attributen <code>cryptoAlgorithmId: String [0..1]</code> und <code>cryptoObjectType: String [0..1]</code>.</li>\n<li>Zwischen <code>CryptoKeySlotDesign</code> und <code>CryptoKeySlotDesignDescription</code> besteht eine neue Kompositionsbeziehung mit Rollenname <code>+algorithmDescription</code>, Kardinalität <code>0..*</code> und Stereotyp <code>«atpSplitable»</code>.</li>\n</ul>"}]};
